import{c as t,Q as i,j as r,m as o}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Hyperliquid Recovery Bot: Flagged Address Solution | Hyperliquid Recovery Bot","description":"Detailed user guide for Hyperliquid Recovery Bot: Flagged Address Solution of Hyperliquid Recovery Bot, helping recover flagged account balances.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/en/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/"}],["meta",{"name":"keywords","content":"Hyperliquid, Recovery Bot, flagged address, Hyperliquid Recovery Bot: Flagged Address Solution"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Hyperliquid Recovery Bot: Flagged Address Solution | Hyperliquid Recovery Bot"}],["meta",{"property":"og:description","content":"Detailed user guide for Hyperliquid Recovery Bot: Flagged Address Solution of Hyperliquid Recovery Bot, helping recover flagged account balances."}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/en/"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Hyperliquid Recovery Bot: Flagged Address Solution | Hyperliquid Recovery Bot"}],["meta",{"name":"twitter:description","content":"Detailed user guide for Hyperliquid Recovery Bot: Flagged Address Solution of Hyperliquid Recovery Bot, helping recover flagged account balances."}]]},"headers":[],"relativePath":"en/index.md","filePath":"en/README.md","lastUpdated":null}'),a={name:"en/index.md"};function s(l,e,n,d,c,u){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="hyperliquid-recovery-bot-flagged-address-solution" tabindex="-1">Hyperliquid Recovery Bot: Flagged Address Solution <a class="header-anchor" href="#hyperliquid-recovery-bot-flagged-address-solution" aria-label="Permalink to &quot;Hyperliquid Recovery Bot: Flagged Address Solution&quot;">​</a></h1><p>Hyperliquid Recovery Bot is a Telegram assistant that helps users recover assets from flagged or restricted Hyperliquid addresses.</p><p><img src="https://img.shields.io/badge/Hyperliquid-Recovery%20Bot-blue" alt="Hyperliquid Recovery Bot"><img src="https://img.shields.io/badge/version-2.7.0-green" alt="Version"><img src="https://img.shields.io/badge/license-MIT-blue" alt="License"><img src="https://img.shields.io/badge/last%20updated-2026--03-brightgreen" alt="Last Updated"></p><blockquote><p>💡 <strong>Need immediate help?</strong> <a href="#start-here">Jump directly to Recovery Instructions</a> to start rescuing your assets.</p></blockquote><h2 id="product-positioning" tabindex="-1">Product Positioning <a class="header-anchor" href="#product-positioning" aria-label="Permalink to &quot;Product Positioning&quot;">​</a></h2><p>This tool is a dedicated Telegram recovery assistant for users whose address can connect in the frontend but cannot operate assets due to high-risk restrictions.</p><p>Typical frontend warning in this scenario:</p><blockquote><p>Action blocked: Address flagged for suspicious activity. Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.</p></blockquote><p>In this scenario, the frontend typically shows a red warning overlay and disables or restricts common operation buttons. The bot helps you check what can be handled now, guides you through recovery, and sends funds back to the same address on Arbitrum.</p><h2 id="who-should-use-this" tabindex="-1">Who Should Use This <a class="header-anchor" href="#who-should-use-this" aria-label="Permalink to &quot;Who Should Use This&quot;">​</a></h2><ul><li>You can access the private key or mnemonic for the address but typically cannot fully operate it in the Hyperliquid frontend.</li><li>You want a guided recovery flow instead of handling everything manually.</li><li>You need clear fee disclosure before executing the emergency withdrawal.</li></ul><h2 id="what-you-get" tabindex="-1">What You Get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What You Get&quot;">​</a></h2><ul><li>Full account detection across spot assets, perpetual positions, vault assets, and staked assets.</li><li>A guided multi-step recovery flow with real-time progress.</li><li>Unified fee presentation: Service Fee, Withdrawal Fees, Total Cost, You Will Receive.</li><li>On-chain verifiability with transaction hashes.</li></ul><h2 id="recovery-scope" tabindex="-1">Recovery Scope <a class="header-anchor" href="#recovery-scope" aria-label="Permalink to &quot;Recovery Scope&quot;">​</a></h2><ul><li><strong>Spot assets</strong>: non-USDC assets are sold to USDC.</li><li><strong>Perpetual positions</strong>: eligible positions are closed as part of recovery.</li><li><strong>Vault assets</strong>: assets that can be withdrawn now are handled first; temporarily unavailable assets are left for a later run.</li><li><strong>Staked assets</strong>: the bot handles staking-related balances step by step and tells you when to run again if waiting is required.</li></ul><h2 id="security-principles" tabindex="-1">Security Principles <a class="header-anchor" href="#security-principles" aria-label="Permalink to &quot;Security Principles&quot;">​</a></h2><ul><li>Use only the official bot entry.</li><li>Never provide your private key or mnemonic to any person, group, form, or website outside the bot&#39;s official recovery flow.</li><li>Use transaction hashes and on-chain results to verify what was completed.</li></ul><h2 id="fee-principles" tabindex="-1">Fee Principles <a class="header-anchor" href="#fee-principles" aria-label="Permalink to &quot;Fee Principles&quot;">​</a></h2><ul><li><strong>Service Fee</strong>: 0.5% of recovered value, minimum 1 USDC.</li><li><strong>Withdrawal Fees</strong>: 2 USDC total (two Hyperliquid withdrawals, 1 USDC each).</li><li><strong>Total Cost</strong>: Service Fee + Withdrawal Fees.</li><li><strong>You Will Receive</strong>: Estimated Recoverable Value - Total Cost.</li></ul><h2 id="start-here" tabindex="-1">Start Here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start Here&quot;">​</a></h2><ol><li>Open bot: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">https://t.me/HyperliquidRecoveryBot</a></li><li>Read <a href="./quick-start">Quick Start</a></li><li>Review <a href="./asset-recovery">Asset Recovery</a></li><li>Check <a href="./fee-and-settlement">Fee and Settlement</a></li><li>Review <a href="./security-and-privacy">Security and Privacy</a></li></ol><h2 id="operational-notes" tabindex="-1">Operational Notes <a class="header-anchor" href="#operational-notes" aria-label="Permalink to &quot;Operational Notes&quot;">​</a></h2><ul><li>Final withdrawal goes to the Arbitrum address corresponding to the source address (same address).</li><li>Settlement is not always instant after withdrawal submission. Arrival time depends on Hyperliquid processing and may take several to more than ten minutes.</li><li>Result pages may show: <code>completed</code>, <code>partial</code>, <code>waiting_to_rerun</code>, or <code>failed</code>.</li><li><code>partial</code> means some assets were handled, but more work may still be needed.</li><li><code>waiting_to_rerun</code> means the bot needs you to come back later after a waiting period ends.</li><li>If nothing could be handled yet, the result will not be shown as <code>completed</code>.</li></ul><h2 id="need-help" tabindex="-1">Need Help <a class="header-anchor" href="#need-help" aria-label="Permalink to &quot;Need Help&quot;">​</a></h2><ul><li>Read <a href="./faq">FAQ</a></li><li>Check <a href="./execution-status">Execution Status</a></li><li>Contact support through in-bot feedback</li></ul>',25)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
